using System;using System.IO;using System.Collections;using System.Collections.Generic;using UnityEngine;
// Private validation fixture; no recovered game source is distributed with public tools.
public static class PortSphereAudit {
 [Serializable] class Report {public string phase,saveName,scope="Design/build completion and painting fixtures; no launcher/sail transport or mouse placement proof";public int layerId,nodeCount,frameCount,shellCount,vertices,meshVertices,structurePoints,cellPoints,paintCells;public long powerBefore,powerAfter;public bool reloadPreserved,paintPreserved;public List<string> errors=new List<string>();}
 static Report report;static int starIndex;static int[] nodes,frames;static int shellId;static byte[] colorBytes;static string Folder=>Application.persistentDataPath;
 static DysonSphere Sphere=>GameMain.data.dysonSpheres[starIndex];static DysonSphereLayer Layer=>Sphere.layersIdBased[report.layerId];
 static void Write(string phase){report.phase=phase;File.WriteAllText(Path.Combine(Folder,"sphere-audit.json"),JsonUtility.ToJson(report,true));Debug.Log("PORT_SPHERE "+phase);}
 static void Check(bool ok,string why){if(!ok)throw new Exception(why);}
 static byte[] Bytes(Color32[] colors){if(colors==null)return new byte[0];var b=new byte[colors.Length*4];for(int i=0;i<colors.Length;i++){b[i*4]=colors[i].r;b[i*4+1]=colors[i].g;b[i*4+2]=colors[i].b;b[i*4+3]=colors[i].a;}return b;}
 static bool Equal(byte[] a,byte[] b){if(a.Length!=b.Length)return false;for(int i=0;i<a.Length;i++)if(a[i]!=b[i])return false;return true;}
 static void Describe(){var l=Layer;report.nodeCount=l.nodeCursor-1-l.nodeRecycleCursor;report.frameCount=l.frameCursor-1-l.frameRecycleCursor;report.shellCount=l.shellCursor-1-l.shellRecycleCursor;var sh=l.shellPool[shellId];report.vertices=sh.vertexCount;report.meshVertices=sh.mesh==null?0:sh.mesh.vertexCount;report.cellPoints=sh.nodecps[sh.nodecps.Length-1];report.structurePoints=0;foreach(var id in nodes)report.structurePoints+=l.nodePool[id].sp;foreach(var id in frames)report.structurePoints+=l.framePool[id].spA+l.framePool[id].spB;}
 static IEnumerator Capture(string suffix){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(Path.Combine(Folder,"sphere-"+suffix+".png"),t.EncodeToPNG());}finally{UnityEngine.Object.Destroy(t);}yield return null;}
 static IEnumerator Run(){
  report=new Report();Write("starting");starIndex=GameMain.localStar.index;var sphere=GameMain.data.CreateDysonSphere(starIndex);var layer=sphere.layersSorted[0];report.layerId=layer.id;
  Check(layer.nodeCursor==1,"Expected empty independent sphere layer");UIRoot.instance.uiGame.OpenDysonEditor();var editor=UIRoot.instance.uiGame.dysonEditor;editor.selection.SetViewStar(GameMain.localStar);editor.selection.AddLayerSelection(layer.id);yield return new WaitForSecondsRealtime(2);
  var centre=Quaternion.Inverse(layer.currentRotation)*editor.screenCamera.transform.position.normalized;var right=Vector3.Cross(centre,Vector3.up).normalized;var up=Vector3.Cross(right,centre).normalized;nodes=new int[4];frames=new int[4];float[] xs={-.2f,.2f,.2f,-.2f},ys={-.2f,-.2f,.2f,.2f};
  for(int i=0;i<4;i++)nodes[i]=layer.NewDysonNode(0,(centre+right*xs[i]+up*ys[i]).normalized*layer.orbitRadius);
  for(int i=0;i<4;i++){frames[i]=layer.NewDysonFrame(0,nodes[i],nodes[(i+1)%4],false);Check(frames[i]>0,"Frame create failed");}
  shellId=layer.NewDysonShell(0,new List<int>(nodes));Check(shellId>0,"Shell create failed");Describe();Check(report.vertices>0&&report.meshVertices>0,"Shell geometry missing");Write("design_created");yield return new WaitForSecondsRealtime(2);yield return Capture("design");
  foreach(int id in nodes){var n=layer.nodePool[id];int guard=0;while(n.spReqOrder>0&&guard++<100000){sphere.OrderConstructSp(n);sphere.ConstructSp(n);}Check(n.spReqOrder==0,"SP completion timeout");guard=0;while(n.cpReqOrder>0&&guard++<100000){n.cpOrdered++;Check(n.ConstructCp()!=null,"CP construction failed");sphere.needRecalculatePower=true;}Check(n.cpReqOrder==0,"CP completion timeout");}
  foreach(int id in nodes){var n=layer.nodePool[id];n.color=new Color32(30,180,240,255);sphere.UpdateColor(n);}
  foreach(int id in frames){var f=layer.framePool[id];f.color=new Color32(240,100,30,255);sphere.UpdateColor(f);}
  var shell=layer.shellPool[shellId];shell.color=new Color32(50,160,240,180);shell.SetMaterialDynamicVars();
  layer.SetPaintingGrid(0);int count=editor.paintingGrids[0].cellCount;Check(count>0,"Painting grid unavailable");var colors=new Color32[count];for(int i=0;i<count;i++)colors[i]=new Color32((byte)(i%2==0?25:240),120,210,72);layer.SetPaintingData(colors);colorBytes=Bytes(colors);report.paintCells=count;
  Write("built_painted");yield return new WaitForSecondsRealtime(4);Describe();report.powerBefore=sphere.energyGenCurrentTick;Check(report.powerBefore>0,"Completed sphere produces no power");yield return Capture("built-painted");
  editor.brushMode=UIDysonEditor.EBrushMode.Paint;yield return new WaitForSecondsRealtime(3);yield return Capture("paint-mode");UIRoot.instance.uiGame.dysonEditor._Close();yield return null;
  report.saveName="PortSphere-"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss");Check(GameSave.SaveCurrentGame(report.saveName),"Sphere save failed");int sp=report.structurePoints,cp=report.cellPoints,verts=report.meshVertices;yield return null;DSPGame.StartGame(report.saveName);Write("reloading");yield return null;
  float deadline=Time.realtimeSinceStartup+180;while((!GameMain.isRunning||DSPGame.IsMenuDemo||GameMain.localPlanet==null||!GameMain.localPlanet.factoryLoaded)&&Time.realtimeSinceStartup<deadline)yield return new WaitForSecondsRealtime(1);
  Check(GameMain.isRunning&&!DSPGame.IsMenuDemo&&GameMain.localPlanet!=null&&GameMain.localPlanet.factoryLoaded,"Reload timeout");yield return new WaitForSecondsRealtime(3);Describe();report.powerAfter=Sphere.energyGenCurrentTick;
  report.reloadPreserved=report.nodeCount==4&&report.frameCount==4&&report.shellCount==1&&report.structurePoints==sp&&report.cellPoints==cp&&report.meshVertices==verts&&report.powerAfter==report.powerBefore;
  report.paintPreserved=Equal(colorBytes,Bytes(Layer.cellColors))&&Layer.nodePool[nodes[0]].color.b==240&&Layer.framePool[frames[0]].color.r==240&&Layer.shellPool[shellId].color.a==180;
  Check(report.reloadPreserved,"Sphere data or power changed after reload");Check(report.paintPreserved,"Painting data lost after reload");UIRoot.instance.uiGame.OpenDysonEditor();editor=UIRoot.instance.uiGame.dysonEditor;editor.selection.SetViewStar(GameMain.localStar);editor.selection.AddLayerSelection(report.layerId);yield return new WaitForSecondsRealtime(3);yield return Capture("reloaded");UIRoot.instance.uiGame.dysonEditor._Close();yield return null;Write("passed");
 }
 public static IEnumerator SafeRun(){var run=Run();while(true){bool more=false;object next=null;Exception error=null;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception e){error=e;}if(error!=null){report.errors.Add(error.ToString());Write("failed");Debug.LogError("Sphere audit failed: "+error);break;}if(!more)break;yield return next;}((IDisposable)run).Dispose();}
}
